visual.raw:
const labelMap = {
  pending: '待审核',
  active: '在读',
  dropout: '已退学',
  finished: '已结业'
};
const rows = (ctx.data && ctx.data.objects) || [];
const data = rows.map(function (r) {
  return { name: labelMap[r.status] || r.status, value: Number(r.stuCount) || 0 };
});
return {
  tooltip: { trigger: 'item' },
  legend: { bottom: 0 },
  series: [
    { type: 'pie', radius: '62%', name: '学籍状态分布', data: data, label: { formatter: '{b}: {c}' } }
  ]
};
